package com.yeyamo_mobile.api.payment_service.application;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.data.domain.*;import com.yeyamo_mobile.api.payment_service.application.port.PaymentOutboxPort;import com.yeyamo_mobile.api.payment_service.infrastructure.persistence.*;
class AdminPaymentServiceTest{PaymentRepository payments=mock(PaymentRepository.class);RefundRepository refunds=mock(RefundRepository.class);ReconciliationJobRepository jobs=mock(ReconciliationJobRepository.class);PaymentOutboxPort outbox=mock(PaymentOutboxPort.class);AdminPaymentService service=new AdminPaymentService(payments,refunds,jobs,outbox);
 @Test void listUsesDatabasePagination(){when(payments.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(Page.empty());assertTrue(service.list("x",null,null,null,null,null,null,null,null,null,null,PageRequest.of(0,20)).isEmpty());verify(payments).findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class));}
 @Test void detectsOnlyPersistedAnomalies(){UUID id=UUID.randomUUID();when(payments.duplicateProviderTransactions()).thenReturn(List.of("provider-1"));when(refunds.inconsistentRefundPayments()).thenReturn(List.of(id));var anomalies=service.anomalies();assertEquals(2,anomalies.size());assertEquals(id,anomalies.get(1).paymentId());}
 @Test void reconciliationCreatesAuditedAsyncJob(){when(jobs.save(any())).thenAnswer(i->i.getArgument(0));var response=service.reconcile("admin","corr");assertEquals("QUEUED",response.status());verify(outbox).append(eq("RECONCILIATION_STARTED"),eq(response.jobId().toString()),eq("corr"),anyMap());}}
